// SRP group parameters (N = safe prime, g = generator), per RFC 5054
// Appendix A. Values here are cross-verified against two independent,
// unrelated open-source implementations (jsrp, which cites RFC 5054
// directly, and the crypto-browserify/diffie-hellman RFC 3526 group table
// for the sizes RFC 5054 reuses from IKE) rather than retyped from memory,
// and each N's bit length and oddness were checked programmatically before
// being committed here.
//
// Default export is the 3072-bit group: >128-bit classical security
// margin, small enough that BigInt modexp in plain JS is still fast
// (a handful of milliseconds per exponentiation on commodity hardware).

const GROUPS = {
  2048: {
    bits: 2048,
    N: '',
    g: '02'
  },
  3072: {
    bits: 3072,
    N: '',
    g: '05'
  },
  4096: {
    bits: 4096,
    N: '',
    g: '05'
  }
}

GROUPS.DEFAULT = GROUPS[3072]

export default GROUPS
